from lib import *
S = SS('x24')
steps = [
    step("没有配置执行器时 @Async 用什么线程池。纯 Spring:100 次 @Async 调用(每次 30 ms)用了 100 个不同的线程,线程名是 SimpleAsyncTaskExecutor-1、SimpleAsyncTaskExecutor-10 这样的——每次调用新建一个线程,没有池。Spring Boot(自动配置了 applicationTaskExecutor):同样 100 次调用只用了 8 个线程 task-1 到 task-8。自己配 ThreadPoolTaskExecutor(核心 4):4 个线程 pool-1 到 pool-4;100 个任务全部完成。纯 Spring 的默认没有池,压力大时线程数会失控。", t=tl(S(1)), mark=lidx(S(1), '纯 Spring,@EnableAsync 没有配置执行器'), done=lidx(S(1), 'Spring Boot(@EnableAutoConfiguration', '配了 ThreadPoolTaskExecutor'), b=bars([['纯 Spring 默认:100 次调用的线程数', 100, '100(每次新线程)'], ['Spring Boot 默认:线程数', 8, '8(applicationTaskExecutor)'], ['自己配核心 4:线程数', 4, '4']], 100, mark=[0], done=[1, 2]), kv=KV([['纯 Spring', 'SimpleAsyncTaskExecutor,每次新建线程'], ['Boot', 'applicationTaskExecutor,8 个线程'], ['自己配', 'ThreadPoolTaskExecutor,核心 4'], ['风险', '纯 Spring 默认不限制线程数']], ['风险'])),
    step("异常去哪了。(a)默认:void 方法抛的异常被 SimpleAsyncUncaughtExceptionHandler 记成一条 ERROR 日志(Unexpected exception occurred invoking async method: public void ...boomVoid()),调用者什么也不知道;返回 CompletableFuture 的方法,异常放进 Future,get() 抛 ExecutionException,原因是 IllegalStateException;@Async 方法返回 String 则调用时就抛 IllegalArgumentException:Invalid return type for async method (only Future and void supported)。(b)自定义 AsyncUncaughtExceptionHandler:void 方法的异常交给它(收到“void 方法里的异常”,方法 boomVoid);其它两种行为不变。", t=tl(S(2)), mark=lidx(S(2), 'returnsString()', 'SimpleAsyncUncaughtExceptionHandler'), done=lidx(S(2), 'boomFuture() 返回的 Future', '自定义 AsyncUncaughtExceptionHandler 收到'), b=bars([['void 方法的异常调用者能看到', 0, '否(只有日志或处理器)'], ['Future 方法的异常', 1, 'get() 抛 ExecutionException'], ['返回 String 的 @Async', 0, '调用时抛 IllegalArgumentException']], 1, mark=[0, 2], done=[1]), kv=KV([['void', '默认只记 ERROR 日志'], ['CompletableFuture', 'get() 抛 ExecutionException'], ['返回 String', 'IllegalArgumentException(只支持 Future 和 void)'], ['自定义处理器', '接管 void 方法的异常']], ['void'])),
    step("ThreadLocal 能不能带到异步线程。没有 TaskDecorator:提交线程里 ThreadLocal 是“请求-42”,异步线程 pool-1 里读到的是 null。给执行器加了一个复制 ThreadLocal 的 TaskDecorator(提交时取值、在任务里设置、结束时清除):异步线程 deco-1 里读到“请求-42”。MDC、SecurityContext、请求上下文这类基于 ThreadLocal 的上下文,到了 @Async 线程就丢了,要用 TaskDecorator 之类的办法传递。", t=tl(S(3)), mark=lidx(S(3), '没有 TaskDecorator'), done=lidx(S(3), '加了 TaskDecorator'), b=bars([['没有 TaskDecorator:异步线程读到', 0, 'null'], ['加了 TaskDecorator:异步线程读到', 1, '请求-42']], 1, mark=[0], done=[1]), kv=KV([['ThreadLocal', '默认不跨线程'], ['TaskDecorator', '提交时取值,任务里设置,结束清除'], ['受影响的', 'MDC、SecurityContext、请求属性'], ['清理', '任务结束要 remove,防止线程池串值']], ['TaskDecorator'])),
    step("执行器满了。核心 2、最大 2、队列 2,同时提交 10 个各 300 ms 的任务。默认拒绝策略:提交本身只花 3 ms,被拒绝 6 个(TaskRejectedException),最终完成 4 个(2 个在跑、2 个在队列),只有 sat-1、sat-2 执行过。CallerRunsPolicy:提交花了 915 ms,被拒绝 0 个,最终完成 10 个,main 线程也执行了任务(调用者在自己的线程里跑,相当于给调用者反压)。", t=tl(S(4)), mark=lidx(S(4), '默认拒绝策略'), done=lidx(S(4), 'CallerRunsPolicy'), b=bars([['默认策略:被拒绝', 6, '6'], ['默认策略:完成', 4, '4'], ['CallerRuns:被拒绝', 0, '0'], ['CallerRuns:完成', 10, '10'], ['CallerRuns:提交耗时 ms', 915, '915']], 915, mark=[0], done=[1, 2, 3], cur=[4]), kv=KV([['容量', '2 个线程加 2 个队列 = 4 个'], ['默认拒绝', '多出的 6 个抛 TaskRejectedException'], ['CallerRuns', '多出的在调用者线程里执行,提交变慢'], ['选择', '丢任务还是拖慢调用者']], ['选择'])),
    step("@Async 的内部调用。从外部调用 @Async 方法 who():执行线程是 pool-1。但是 callInternal() 里 this.fire(0) 的调用者线程是 main——内部调用不经过代理,@Async 不生效,同步执行(和自调用篇的结论一致)。", t=tl(S(5)), mark=lidx(S(5), 'callInternal'), b=bars([['外部调用 @Async 方法', 1, '异步(pool-1)'], ['内部 this 调用 @Async 方法', 0, '同步(main)']], 1, done=[0], mark=[1]), kv=KV([['外部调用', 'pool-1 线程'], ['内部调用', 'main 线程,同步'], ['原因', '内部调用不经过代理'], ['办法', '拆成两个 Bean,见自调用篇']], ['内部调用'])),
]
